    if not isinstance(nodes, list):
        nodes = list(nodes) if hasattr(nodes, '__iter__') else []
    if not isinstance(edges, list):
        edges = list(edges) if hasattr(edges, '__iter__') else []
    # Initialize Union-Find
    parent = {node: node for node in nodes}
    def find(x):
        # Path compression
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[ry] = rx
    # Process edges
    for u, v in edges:
        if u in parent and v in parent:
            union(u, v)
    # Build components
    components = {}
    for node in nodes:
        root = find(node)
        components.setdefault(root, []).append(node)
    # Sort each component
    result = [sorted(comp) for comp in components.values()]
